        "art": "ranger",
        "skin": "#e8b888",
        "shirt": "#3a6ac0",
        "pants": "#2a3a4a",
        "hair": "#1a1a1a",
        "dialogue": [
          "Twenty years tending these lawns. The Sunflora by the pond are my pension plan.",
          "Trainers rest here between cities. The park insists on it."
        ]
